def upd(r):
    k=r['stock_code']
    if k not in R: return
    lv,pct,dec=R[k]; v=rows[k]; tot=t86[k]['total']
    r['actual_close']=v['cl']; r['close_price']=v['cl']; r['current_price']=v['cl']; r['change_percent']=v['chg']; r['return_pct_at_close']=v['ret']
    r['result']='holding'; r['holding_days']=v['D']; r['holding_days_label']=f"D{v['D']}/10"
    base=f"收盤 {v['cl']}（今日 {v['chg']:+.2f}%，相對推薦價 {v['ret']:+.2f}%）；10-05 T86 {tot:+,} 張"
    if dec=='exit':
        r['holding_status']=f"🛑 10-06 開盤出場（鐵律③ L4）：{base}＝{pct}%（≥8%，avg_5day_volume 分母、16:23 取樣），不受 v8.3.3 保護；入帳價用 10-06 收盤（v8.3.2）{EXTRA.get(k,'')}"
    elif dec=='pending':
        r['holding_status']=f"⚠️ 待複核（v8.3.3）：{base}＝{pct}%（L4，<8%）且 10 日累計三大法人 {CUM[k]:+,} 張為正 → 不開盤出場；10-06 12:30 與盤後各複核一次，兩次皆 ≥5% 才於 10-07 開盤出場；鐵律①② 無觸發（距停損 {v['dist_stop']:+.2f}%）{EXTRA.get(k,'')}"
    else:
        r['holding_status']=f"續抱：{base}（{lv}）；鐵律①②③ 無觸發；距停損 {v['dist_stop']:+.2f}%、距目標 {v['dist_target']:.2f}%{EXTRA.get(k,'')}"
    r['reversal_level_1005t86']=lv; r['sell_ratio_pct_1005t86']=pct
for r in t['recommendations']: upd(r)
